mapper.sql:
WHERE m.delete_yn = 'N'

    AND (m.bbs_code LIKE CONCAT('%', #{keywordLike}, '%') ESCAPE '|'
      OR m.bbs_name LIKE CONCAT('%', #{keywordLike}, '%') ESCAPE '|')

AND m.site_id = #{siteId}
AND m.bbs_type = #{bbsType}

mapper.select:
SELECT COUNT(*) FROM tb_bbs_master
WHERE site_id = #{siteId} AND bbs_code = #{bbsCode} AND delete_yn = 'N'
AND bbs_master_id <> #{excludeId}

SELECT bbs_master_id, bbs_code, bbs_name, bbs_type
FROM tb_bbs_master
WHERE delete_yn = 'N' AND use_yn = 'Y'
AND site_id = #{siteId}
  AND (grouped_board_ids IS NULL OR grouped_board_ids = ''
OR bbs_master_id = #{selfId}
      )
ORDER BY bbs_code
